CREATE OR REPLACE FUNCTION depot_document_insertion_seule() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'depot_document est en insertion seule (RG-04, RG-16)';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER tr_depot_document_insertion_seule
    BEFORE UPDATE OR DELETE ON depot_document
    FOR EACH ROW EXECUTE FUNCTION depot_document_insertion_seule();
